// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;
    function setUp() public { c = new PrivateBank(address(new Log())); }
    function testFuzz_property(address actor, uint256 extra) public {
        vm.assume(actor != address(0) && actor != address(c));
        extra = bound(extra, 0, 100 ether);
        uint256 value = 1 ether + extra;
        vm.deal(actor, value);
        vm.prank(actor);
        c.Deposit{value: value}();
        assertTrue(c.balances(actor) == value, "deposit of value >= MinDeposit must be credited");
    }
}
